class Solution {
public:
    int maxEqualFreq(vector<int>& nums) {
        unordered_map<int, int> freq, freqCount;
        int maxFreq = 0, answer = 0;
        for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
            int x = nums[i];
            int old = freq[x];
            if (old) --freqCount[old];
            int now = ++freq[x];
            ++freqCount[now];
            maxFreq = max(maxFreq, now);
            int len = i + 1;
            bool valid = (maxFreq == 1) ||
                (freqCount[1] == 1 &&
                 1LL * (maxFreq) * freqCount[maxFreq] + 1 == len) ||
                (freqCount[maxFreq] == 1 &&
                 1LL * (maxFreq - 1) * freqCount[maxFreq - 1] + maxFreq == len);
            if (valid) answer = len;
        }
        return answer;
    }
};
